ee:variables.ee:set-variable:
%dw 2.0
output application/java
var physical = not isEmpty(vars.vOrder.items filter ($.'type' == "PHYSICAL"))
var digital = not isEmpty(vars.vOrder.items filter ($.'type' == "DIGITAL"))
var international = upper(vars.vOrder.country) != upper(p('eip.orders.homeCountry'))
---
["invoicing"]
	++ (if (physical) ["warehouse"] else [])
	++ (if (digital) ["digitalDelivery"] else [])
	++ (if (physical and international) ["customs"] else [])
